1	// csrc/fused/sm_90/mega_decoder_real_adamw_tc.cu — R2.3 TENSOR-CORE cell driver
2	// TU (DESIGN-TC-PIPELINE.md Fork B). The bf16 wgmma fwd+bwd+AdamW persistent
3	// megakernel, compiled with -DSG_TUNED_GEMM_IMPL=1 so the wgmma branch of
4	// fused_decoder_megakernel.cuh is selected (the scalar default TU
5	// mega_decoder_real_adamw.cu is UNTOUCHED and ships as the live path).
6	//
7	// BUILD-ONLY extension of the build path (the R2.3 deliverable (2)): this is a
8	// SECOND compiled TU for the SAME (decoder × adamw) cell, selected by the GEMM
9	// impl token. It is NOT wired into compile.py / dispatch — the parity gate
10	// (tests/hw/test_decoder_tc.py PART 2) JIT-loads it via cpp_extension.load and
11	// drives it directly through the pybind entry below (mirroring the scalar
12	// dispatch.cpp:630-651 launch). No setup.py glob change, no dispatch routing.
13	//
14	// The pybind entry `tc_train_step` runs ONE Fork-B TC step over a flat fp32
15	// param blob in place, returning (mean loss, reduced weight grad [total]) so the
16	// gate can compare every grad per-tensor vs the bf16-rounded fp64 oracle (the
17	// keystone validation — the CPU mirror does NOT cover tile-batched P1).
18	//
19	// HONESTY: this exercises the REAL tensor-core path (HGMMA in SASS, verified by
20	// the SASS audit in test_decoder_tc.py). No scalar fallback, no surrogate.
21	
22	#define SG_TUNED_GEMM_IMPL 1   // select the wgmma cell driver
23	
24	#include <torch/extension.h>
25	#include <c10/cuda/CUDAStream.h>
26	#include <c10/cuda/CUDAException.h>
27	#include <cuda_runtime.h>
28	#include <cstdint>
29	
30	#include "csrc/fused/sm_90/fused_decoder_megakernel.cuh"
31	
32	namespace dec = ::sg::fused::sm90::dec;
33	using ::sg::fused::PersistentContext;
34	using ::sg::fused::sm90::DecoderTokenCtx;
35	using ::sg::fused::sm90::FusedOptState;
36	using ::sg::fused::sm90::OptId;
37	using ::sg::fused::sm90::kDecTotalElems;
38	
39	// One persistent set of barrier/queue counters + the TC workspace, cached per
40	// device (the kernel zeroes the barrier per launch; the workspace is sized for
41	// the TC layout, NOT the scalar 223 MB partials). Re-created if a larger B
42	// requires a larger workspace.
43	struct TcScratch {
44	    torch::Tensor g_next;       // int [1]
45	    torch::Tensor g_arrived;    // int [1]
46	    torch::Tensor g_generation; // int [1]
47	    torch::Tensor workspace;    // float [dec_tc_workspace_floats(T,B,nCTA)]
48	    int n_ctas = 0;
49	    int64_t ws_floats = 0;
50	};
51	
52	// Effective nCTA the launcher will use (must match for workspace + ownership).
53	static int tc_effective_nctas(const torch::Tensor& params, int ncta_cap) {
54	    int dev = params.get_device();
55	    int n_sms = 1;
56	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
57	    int n = n_sms;
58	    if (ncta_cap > 0 && ncta_cap < n) n = ncta_cap;
59	    return n;
60	}
61	
62	static TcScratch& tc_scratch_for(const torch::Tensor& params, int B, int nCTA) {
63	    static TcScratch s;
64	    const int T = B * dec::kSeq;
65	    const int64_t need = ::sg::fused::sm90::dec_tc_workspace_floats(T, B, nCTA);
66	    if (!s.g_next.defined()) {
67	        auto opt_i = torch::dtype(torch::kInt32).device(params.device());
68	        s.g_next = torch::zeros({1}, opt_i);
69	        s.g_arrived = torch::zeros({1}, opt_i);
70	        s.g_generation = torch::zeros({1}, opt_i);
71	    }
72	    s.n_ctas = nCTA;
73	    if (s.ws_floats < need) {
74	        auto opt_f = torch::dtype(torch::kFloat32).device(params.device());
75	        s.workspace = torch::empty({need}, opt_f);
76	        s.ws_floats = need;
77	    }
78	    return s;
79	}
80	
81	// tc_train_step: one Fork-B TC step. params [total] fp32 (updated in place);
82	// tokens [B,kSeq] int32; targets [B] int32; state [3*total] fp32 ([m|v|extra]).
83	// Returns {loss (cpu float scalar tensor), grad [total] fp32 (the reduced grad)}.
84	static std::vector<torch::Tensor> tc_train_step(
85	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
86	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
87	        double weight_decay, double bc1, double bc2, int64_t step,
88	        int64_t ncta_cap) {
89	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
90	    TORCH_CHECK(params.numel() == kDecTotalElems, "params must be the flat decoder blob (", kDecTotalElems, ")");
91	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
92	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
93	    const int B = (int)targets.numel();
94	    TORCH_CHECK(tokens.numel() == (int64_t)B * dec::kSeq, "tokens must be [B,kSeq]");
95	    TORCH_CHECK((B % 16) == 0, "TC path requires B %% 16 == 0 (dW K-loop is 16-step atoms)");
96	    const int64_t total = kDecTotalElems;
97	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
98	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
99	
100	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
101	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
102	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
103	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
104	
105	    PersistentContext ctx{
106	        sc.g_next.data_ptr<int>(),
107	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
108	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
109	        ::sg::fused::sm90::kDecNumTensors,
110	        0u};
111	
112	    FusedOptState st;
113	    float* m = state.data_ptr<float>();
114	    st.exp_avg = m;
115	    st.exp_avg_sq = m + total;
116	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
117	    st.eps = (float)eps; st.wd = (float)weight_decay;
118	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
119	
120	    DecoderTokenCtx tok;
121	    tok.tokens = tokens.data_ptr<int>();
122	    tok.targets = targets.data_ptr<int>();
123	    tok.B = B;
124	    tok.workspace = sc.workspace.data_ptr<float>();
125	    tok.loss_out = loss_dev.data_ptr<float>();
126	
127	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
128	    cudaError_t err = ::sg::fused::sm90::launch_fused_decoder_megakernel_tc<OptId::AdamW>(
129	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
130	        (float)lr, (int)step, st, stream, nCTA);
131	    TORCH_CHECK(err == cudaSuccess, "TC megakernel launch failed: ", cudaGetErrorString(err));
132	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
133	
134	    return {loss_dev.to(torch::kCPU), grad};
135	}
136	
137	// CALIBRATION HOOK (test_decoder_tc.py::test_tc_dw_gemm_exact_on_own_operands):
138	// slice the kernel's OWN stored bf16 acts dY_ff2[L1] [T,d] and X_gact[L1] [T,dff]
139	// from the workspace, returned as fp32 CPU tensors. The gate contracts them in
140	// fp32 ascending-t and compares to the kernel's ff2.weight grad slice — isolating
141	// the dW GEMM (incl. the ONLY Kin=dff multi-N-tile path, untested by the 13/13
142	// engine micro-gates) from the operand-chain bf16 divergence. A ~1e-6 match
143	// proves the dW GEMM is bit-exact on its own operands, calibrating the per-tensor
144	// bf16 tolerance as headroom over a GEMM-exact floor. Re-uses the cached
145	// workspace from the last tc_train_step (call AFTER it). Read-only; ships in the
146	// test TU only (never globbed into the .so).
147	static std::vector<torch::Tensor> tc_dump_ff2_operands(torch::Tensor params, int64_t B) {
148	    const int nCTA = tc_effective_nctas(params, 0);  // unused for offsets; acts layout is nCTA-independent
149	    (void)nCTA;
150	    TcScratch& sc = tc_scratch_for(params, (int)B, tc_effective_nctas(params, 4));
151	    const int T = (int)B * dec::kSeq;
152	    const int64_t d = dec::kD, dff = dec::kDff;
153	    auto acts_bf16 = sc.workspace.slice(0, 0, ::sg::fused::sm90::dec_tc_acts_floats(T, (int)B))
154	                         .view(torch::kBFloat16);
155	    // mirror dec_acts_bind: walk to dY_ff2[1] and X_gact[1].
156	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
157	    int64_t off = 0; int64_t off_Xgact1 = -1, off_dYff2_1 = -1;
158	    for (int li = 0; li < dec::kLayers; ++li) {
159	        off += Td;          // X_in
160	        off += Td;          // X_ctx
161	        off += Td;          // X_x1
162	        if (li == 1) off_Xgact1 = off;
163	        off += Tff;         // X_gact
164	        off += T3d;         // dY_qkv
165	        off += Td;          // dY_a
166	        off += Tff;         // dY_ff0
167	        if (li == 1) off_dYff2_1 = off;
168	        off += Td;          // dY_ff2
169	    }
170	    auto Xgact1 = acts_bf16.slice(0, off_Xgact1, off_Xgact1 + Tff).to(torch::kFloat32).to(torch::kCPU);
171	    auto dYff2_1 = acts_bf16.slice(0, off_dYff2_1, off_dYff2_1 + Td).to(torch::kFloat32).to(torch::kCPU);
172	    return {dYff2_1, Xgact1};  // [T*d], [T*dff]
173	}
174	
175	// scalar_train_step: the SAME (decoder × AdamW) cell run through the SCALAR
176	// default launcher (launch_fused_decoder_megakernel<AdamW>, which lives OUTSIDE
177	// the wgmma guard at fused_decoder_megakernel.cuh:253 — so this wgmma-token TU
178	// can still call it). This exists ONLY so the step-time gate can time the live
179	// scalar path and the TC path BACK-TO-BACK in one process / one contention
180	// regime → an honest scalar:TC ratio. The scalar path uses its OWN workspace
181	// layout (nCTA*total grad partials + nCTA loss slots + 1 reduced loss), sized
182	// for nCTA = #SMs (the scalar launcher pins one CTA per SM, no cap). It is NOT
183	// the shipped invocation (that is dispatch.cpp via mega_decoder_real_adamw.cu);
184	// it is a measurement mirror. Returns {loss, reduced grad} like tc_train_step.
185	static std::vector<torch::Tensor> scalar_train_step(
186	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
187	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
188	        double weight_decay, double bc1, double bc2, int64_t step) {
189	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
190	    TORCH_CHECK(params.numel() == kDecTotalElems, "params must be the flat decoder blob (", kDecTotalElems, ")");
191	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
192	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
193	    const int B = (int)targets.numel();
194	    TORCH_CHECK(tokens.numel() == (int64_t)B * dec::kSeq, "tokens must be [B,kSeq]");
195	    const int64_t total = kDecTotalElems;
196	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
197	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
198	
199	    int dev = params.get_device();
200	    int n_sms = 1;
201	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
202	
203	    // Separate cached scalar scratch (DO NOT reuse the TC workspace — different
204	    // layout/size; the TC one under-allocates the scalar nCTA*total partials).
205	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
206	    static int64_t s_ws_floats = 0;
207	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
208	    if (!s_gn.defined()) {
209	        auto oi = torch::dtype(torch::kInt32).device(params.device());
210	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
211	    }
212	    if (s_ws_floats < need) {
213	        s_ws = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
214	        s_ws_floats = need;
215	    }
216	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
217	    float* loss_out = s_ws.data_ptr<float>() + (int64_t)n_sms * total + n_sms;
218	
219	    PersistentContext ctx{
220	        s_gn.data_ptr<int>(),
221	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
222	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
223	        ::sg::fused::sm90::kDecNumTensors, 0u};
224	
225	    FusedOptState st;
226	    float* m = state.data_ptr<float>();
227	    st.exp_avg = m; st.exp_avg_sq = m + total;
228	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
229	    st.eps = (float)eps; st.wd = (float)weight_decay;
230	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
231	
232	    DecoderTokenCtx tok;
233	    tok.tokens = tokens.data_ptr<int>();
234	    tok.targets = targets.data_ptr<int>();
235	    tok.B = B;
236	    tok.workspace = s_ws.data_ptr<float>();
237	    tok.loss_out = loss_out;
238	
239	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
240	    cudaError_t err = ::sg::fused::sm90::launch_fused_decoder_megakernel<OptId::AdamW>(
241	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
242	        (float)lr, (int)step, st, stream);
243	    TORCH_CHECK(err == cudaSuccess, "scalar megakernel launch failed: ", cudaGetErrorString(err));
244	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
245	
246	    auto loss_cpu = s_ws.slice(0, (int64_t)n_sms * total + n_sms, (int64_t)n_sms * total + n_sms + 1)
247	                        .to(torch::kCPU);
248	    return {loss_cpu, grad};
249	}
250	
251	PYBIND11_MODULE(TORCH_EXTENSION_NAME, mm) {
252	    mm.def("tc_train_step", &tc_train_step,
253	           "Fork-B tensor-core decoder fwd+bwd+AdamW step (in place); returns (loss, reduced grad)",
254	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
255	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
256	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
257	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"),
258	           pybind11::arg("ncta_cap") = 0);
259	    mm.def("tc_dump_ff2_operands", &tc_dump_ff2_operands,
260	           "gate-only: dump the kernel's stored dY_ff2[L1], X_gact[L1] (fp32 CPU)");
261	    mm.def("scalar_train_step", &scalar_train_step,
262	           "gate-only: SAME cell via the SCALAR launcher (back-to-back step-time mirror)",
263	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
264	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
265	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
266	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"));
267	    mm.attr("TILE_M") = (int)::sg::fused::sm90::dectc::kTileM;
268	    mm.attr("TILE_N") = (int)SG_TUNED_TILE_N;
269	    mm.attr("TOTAL") = (int)kDecTotalElems;
270	}
