420	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
421	        }
422	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
423	        dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
424	    } else {
425	        for (int gt = cta; gt < n_dw; gt += nCTA)
426	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
427	    }
428	    dectc::dectc_dw_biases(spec, grad);
429	    dectc::dectc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
430	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
431	    // Loss reduce (fp64) by CTA 0.
432	    if (cta == 0 && threadIdx.x == 0) {
433	        double s = 0.0;
434	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
435	        *tok.loss_out = (float)(s / (double)B);
436	    }
437	    (void)loss_out;
438	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
439	
440	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Eager
441	    //    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
442	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
443	    //    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
444	    //    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
445	    //    deterministic ascending reduction (no float atomics): each CTA sums a
446	    //    contiguous element-range into a per-CTA partial slot, CTA0 sums the
447	    //    partials in ascending CTA order → total_norm → clip_coef, broadcast via
448	    //    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
449	    //    + the eager-side clip must both see the unclipped reduced grad); the
450	    //    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
451	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
452	    if constexpr (Opt == OptId::GrokAdamW) {
453	        // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
454	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
455	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
456	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
457	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
458	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
459	        const int64_t total = kDecTotalElems;
460	        const int64_t base = total / nCTA, rem = total % nCTA;
461	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
462	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
463	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
464	        float tsum = 0.0f;
465	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
466	            const float gv = grad[e0 + i];
467	            tsum += gv * gv;
468	        }
469	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
470	        float* red = sm.red;
471	        red[threadIdx.x] = tsum;
472	        __syncthreads();
473	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
474	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
475	            __syncthreads();
476	        }
477	        if (threadIdx.x == 0) sq_part[cta] = red[0];
478	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
479	        // CTA0 ascending-order reduce → total_norm → clip_coef (deterministic).
480	        if (cta == 0 && threadIdx.x == 0) {
481	            double ss = 0.0;
482	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
483	            const float total_norm = sqrtf((float)ss);
484	            float coef = 1.0f;
485	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
486	                coef = st.grad_clip / (total_norm + 1e-6f);
487	            *coef_bc = coef;
488	        }
489	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
490	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
491	    }
492	
493	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
494	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
495	    st.lr = lr;
496	    {
497	        __shared__ int task_slot;
498	        TaskQueue q = ctx.queue();
499	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
500	             t = q.next_block(&task_slot)) {
501	            const int n = kDecSizes[t];
502	            const int64_t off = (int64_t)kDecOffsets[t];
503	            FusedOptState ts = rebase_state<Opt>(st, off);
504	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
505	            //     t == the tensor's flat named_parameters() layer index (the
506	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
507	            //     enumeration order, so t IS the eager layer index). bc1 must be
508	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
509	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
510	            if constexpr (Opt == OptId::GrokAdamW) {
511	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
512	                ts.beta1 = b1;
513	                ts.bc1   = 1.0f - powf(b1, (float)step);
514	            }
515	            float* __restrict__ p = params + off;
516	            const float* __restrict__ gg = grad + off;
517	            for (int i = threadIdx.x; i < n; i += blockDim.x)
518	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
519	        }
520	    }
521	}
