523	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
524	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
525	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
526	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
527	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
528	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
529	// nCTA (the dW/embedding owner maps are functions of nCTA).
530	template <OptId Opt>
531	cudaError_t launch_fused_decoder_megakernel_tc(
532	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
533	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
534	        int ncta_cap = 0) {
535	    int dev = 0;
536	    cudaError_t err = cudaGetDevice(&dev);
537	    if (err != cudaSuccess) return err;
538	    int n_sms = 0;
539	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
540	    if (err != cudaSuccess) return err;
541	
542	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
543	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
544	    // can't place one block/SM, REFUSE (the grid barrier would hang).
545	    int occ = 0;
546	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
547	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
548	        /*dynamicSMemBytes=*/0);
549	    if (err != cudaSuccess) return err;
550	    if (occ < 1) return cudaErrorLaunchOutOfResources;
551	
552	    unsigned launch_ctas = (unsigned)n_sms;
553	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
554	    ctx.n_ctas = launch_ctas;
555	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
556	    // AND it guarantees full token tiles for the projections). NO G-divisibility
557	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
558	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
559	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
560	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
561	
562	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
563	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
564	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
565	
566	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
567	    fused_decoder_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
568	        ctx, params, tok, grad, lr, step, st);
569	    return cudaGetLastError();
570	}
