252	template <OptId Opt>
253	cudaError_t launch_fused_decoder_megakernel(
254	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
255	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
256	    int dev = 0;
257	    cudaError_t err = cudaGetDevice(&dev);
258	    if (err != cudaSuccess) return err;
259	    int n_sms = 0;
260	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
261	    if (err != cudaSuccess) return err;
262	
263	    int occ = 0;
264	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
265	        &occ, (const void*)&fused_decoder_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
266	        /*dynamicSMemBytes=*/0);
267	    if (err != cudaSuccess) return err;
268	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
269	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
270	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
271	    assert(occ >= 1 &&
272	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
273	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
274	           "reduce footprint or fall back to the L1 per-op path.");
275	    if (occ < 1) return cudaErrorLaunchOutOfResources;
276	
277	    const unsigned launch_ctas = (unsigned)n_sms;
278	    ctx.n_ctas = launch_ctas;
279	
280	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
281	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
282	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
283	
284	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
285	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
286	        ctx, params, tok, grad, lr, step, st);
287	    return cudaGetLastError();
288	}
