291	//  WGMMA CELL DRIVER (DESIGN-TC-PIPELINE.md Fork B, R2.3). Compiled only under
292	//  the wgmma token; the scalar path above is untouched.
293	// ════════════════════════════════════════════════════════════════════════════
294	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
295	
296	// TC megakernel threads: 256 (the engine's producer+consumer warpgroup layout;
297	// wgmma is warpgroup-scoped on threads 0..127). We do NOT apply the scalar
298	// path's asymmetric setmaxnreg (dealloc<32> on WG0) — that would STARVE the MMA
299	// warpgroup (WG0 issues the wgmma; a 128-wide accumulator needs 64 fp32 regs/
300	// thread). The validated selftest ran no split; we match it.
301	#define SG_TC_MEGA_BLOCK 256
302	
303	// ── smem arena for the unpipelined engine: one A(64×16) + one B(N×16) bf16 tile
304	//    + the 256-float reduction slot. 16B-aligned. N = SG_TUNED_TILE_N. The 9 dW
305	//    specs live here too (identical for all threads → shared, not per-thread
306	//    stack: keeps the launch's local-memory reservation small so the persistent
307	//    kernel places on a memory-tight GPU). ──
308	struct DecTcSmem {
309	    // kDecTcStages A(64×16) + kDecTcStages B(N×16) bf16 tiles — the GEMM K-loop
310	    // double-buffer ring (slot s at sA + s*64*16 / sB + s*N*16). At S=2 + N=128
311	    // the ring is 2·(2KB+4KB)=12KB; DecTcSmem total ~13.5KB ≪ the 48KB static cap.
312	    __nv_bfloat16 sA[dectc::kDecTcStages * 64 * 16];
313	    __nv_bfloat16 sB[dectc::kDecTcStages * SG_TUNED_TILE_N * 16];
314	    float red[256];
315	    dectc::DecDwSpec spec[9];
316	};
317	
318	// ── TC workspace layout (carved from tok.workspace; the host sizes it for the
319	//    TC path — see dec_tc_workspace_floats). Regions (float units):
320	//      [0 .. acts_f)                      : DecActs bf16 region (reinterpreted)
321	//      [acts_f .. acts_f + nCTA*scratch)  : per-CTA tile scratch (f32)
322	//      [.. + nCTA*kLnVecElems)            : per-CTA LN-vec partials (f32)
323	//      [.. + nCTA)                        : per-CTA loss slots (f32)
324	//      [.. + 1)                           : reduced scalar loss (host reads it)
325	//    acts_f = ceil(acts_bf16 / 2). ──
326	__host__ __device__ __forceinline__ int64_t dec_tc_acts_floats(int T, int B) {
327	    // mirror dectc::dec_acts_bind's running offset (bf16 elems) → floats.
328	    const int64_t d = dec::kD, dff = dec::kDff, V = dec::kVocab, L = dec::kLayers;
329	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
330	    int64_t bf = 0;
331	    for (int li = 0; li < L; ++li) bf += Td + Td + Td + Tff + T3d + Td + Tff + Td;
332	    bf += (int64_t)B * d + (int64_t)B * V + Td;     // X_hn + dY_logits + dh0
333	    return (bf + 1) / 2;
334	}
335	// dW split-K partial floats (0 when G==1 → no extra scratch, single-CTA path).
336	__host__ __device__ __forceinline__ int64_t dec_tc_dw_part_floats() {
337	    return (dectc::kDecDwSplitK > 1) ? dectc::dec_dw_part_floats(dectc::kDecDwSplitK) : 0;
338	}
339	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
340	    return dec_tc_acts_floats(T, B)
341	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
342	         + (int64_t)nCTA * dectc::kLnVecElems
343	         + nCTA + 1
344	         + dec_tc_dw_part_floats();          // split-K dW partials (G>1)
345	}
