347	template <OptId Opt>
348	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
349	fused_decoder_megakernel_tc(PersistentContext ctx,
350	                            float* __restrict__ params,
351	                            DecoderTokenCtx tok,
352	                            float* __restrict__ grad,
353	                            float lr, int step, FusedOptState st) {
354	    __shared__ DecTcSmem sm;
355	    GridBarrier bar = ctx.barrier();
356	    const int cta = blockIdx.x;
357	    const int nCTA = (int)ctx.n_ctas;
358	    const int B = tok.B;
359	    const int T = B * dec::kSeq;
360	
361	    // Workspace partition.
362	    float* ws = tok.workspace;
363	    const int64_t acts_f = dec_tc_acts_floats(T, B);
364	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
365	    float* scratch_base = ws + acts_f;
366	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
367	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
368	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
369	    float* loss_out   = loss_part + nCTA;
370	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
371	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
372	    float* dw_part    = loss_out + 1;
373	    const int kDwG    = dectc::kDecDwSplitK;
374	
375	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
376	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
377	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
378	
379	    DecWeights w = dec_bind(params);
380	
381	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
382	    //    written-once → no pre-zero). ──
383	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
384	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
385	    bar.sync();   // B0
386	
387	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
